-- Hyprland config (Lua). Ported from the legacy hyprland.conf, which Hyprland
-- stops reading in 0.57.
-- Refer to the wiki for more information.
-- https://wiki.hypr.land/Configuring/Start/


------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({ output = "DP-2",     mode = "3440x1440@144",   position = "0x0", scale = 1 })
hl.monitor({ output = "HDMI-A-1", mode = "3440x1440@99.98", position = "0x0", scale = 1 })

-- Theme palette (nord0..nord15) — generated by `theme-switch`
local colors = dofile(os.getenv("HOME") .. "/.config/theme/hypr-colors.lua")


---------------------
---- MY PROGRAMS ----
---------------------

local terminal    = "ghostty"
local fileManager = "dolphin"
local menu        = "pkill wofi || wofi --show drun"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/
hl.on("hyprland.start", function()
    hl.exec_cmd("quickshell")

    -- Bring up the systemd graphical-session.target so xdg-desktop-portal starts.
    -- Without this, the portal's `Requisite=graphical-session.target` is never met and
    -- opening external URLs (e.g. from Obsidian/Flatpak) silently fails.
    hl.exec_cmd("systemctl --user start hyprland-session.target")
    hl.exec_cmd("hyprpaper & sleep 2 && hyprctl hyprpaper preload \"$HOME/.config/hypr/wallpapers/darksouls.png\" ; hyprctl hyprpaper wallpaper \"HDMI-A-1,$HOME/.config/hypr/wallpapers/darksouls.png\"")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("hypridle")
end)


