---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Every bind carries a description, "Group: what it does". `hyprctl binds -j`
-- reports it and the quickshell keys cheatsheet (SUPER+/) groups its columns by
-- the part before the colon. Groups: Agents, Apps, Shell, Windows, Workspaces,
-- Notifications, Capture, Media, Session.
-- Lua binds show up in `hyprctl binds -j` as an opaque id, so each dispatcher is
-- also kept in the global BINDS by description: the cheatsheet runs one with
-- `hyprctl dispatch 'BINDS["Apps: Terminal"]'`.
BINDS = {}
local function bind(keys, description, dispatcher, opts)
    opts = opts or {}
    opts.description = description
    BINDS[description] = dispatcher
    return hl.bind(keys, dispatcher, opts)
end

local function exec(cmd) return hl.dsp.exec_cmd(cmd) end
local function global(name) return hl.dsp.global(name) end

bind(mainMod .. " + Q",          "Apps: Terminal",         exec(terminal))
bind(mainMod .. " + C",          "Windows: Close window",  hl.dsp.window.close())
bind(mainMod .. " + M",          "Session: Power menu",    exec("powermenu"))
bind(mainMod .. " + Escape",     "Session: Power menu",    exec("powermenu"))
bind(mainMod .. " + CTRL + L",   "Session: Lock screen",   exec("loginctl lock-session")) -- hypridle runs hyprlock
bind(mainMod .. " + E",          "Apps: File manager",     exec(fileManager))
bind(mainMod .. " + V",          "Windows: Toggle floating", hl.dsp.window.float({ action = "toggle" }))
bind(mainMod .. " + F",          "Windows: Maximise",      hl.dsp.window.fullscreen({ mode = "maximized" }))
bind(mainMod .. " + SHIFT + F",  "Windows: Fullscreen",    hl.dsp.window.fullscreen({ mode = "fullscreen" }))
bind(mainMod .. " + R",          "Apps: Launcher",         exec(menu))
bind(mainMod .. " + SHIFT + S",  "Capture: Screenshot",    exec("flameshot gui"))
bind(mainMod .. " + ALT + S",    "Capture: Record full screen", exec("screen-record"))
bind(mainMod .. " + CTRL + S",   "Capture: Record a region",    exec("screen-record --region"))
bind(mainMod .. " + W",          "Shell: Toggle bar",      global("quickshell:togglebar"))
bind(mainMod .. " + SHIFT + W",  "Shell: Dashboard",       global("quickshell:toggledashboard"))
bind(mainMod .. " + SHIFT + V",  "Apps: Clipboard history", exec("cliphist list | wofi --dmenu | cliphist decode | wl-copy"))

-- Agent board (docs/agent-board.md): quickshell roster, checklist wall, keys cheatsheet
bind(mainMod .. " + G",          "Agents: Roster",         global("quickshell:roster"))
bind(mainMod .. " + SHIFT + G",  "Agents: Checklist wall", global("quickshell:wall"))
bind(mainMod .. " + slash",      "Agents: Keys cheatsheet", global("quickshell:keys"))
bind(mainMod .. " + N",          "Agents: Jump to what needs you", exec("board next"))
bind(mainMod .. " + down",       "Windows: Toggle split",  hl.dsp.layout("togglesplit")) -- dwindle

-- Move focus with mainMod + hjkl (vim-style)
bind(mainMod .. " + H", "Windows: Focus left",  hl.dsp.focus({ direction = "left" }))
bind(mainMod .. " + L", "Windows: Focus right", hl.dsp.focus({ direction = "right" }))
bind(mainMod .. " + K", "Windows: Focus up",    hl.dsp.focus({ direction = "up" }))
bind(mainMod .. " + J", "Windows: Focus down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    bind(mainMod .. " + " .. key,         "Workspaces: Go to workspace " .. i,          hl.dsp.focus({ workspace = i }))
    bind(mainMod .. " + SHIFT + " .. key, "Workspaces: Move window to workspace " .. i, hl.dsp.window.move({ workspace = i }))
end

-- Special workspace (scratchpad)
bind(mainMod .. " + A",         "Workspaces: Magic workspace",     hl.dsp.workspace.toggle_special("magic"))
bind(mainMod .. " + SHIFT + A", "Workspaces: Move window to magic", hl.dsp.window.move({ workspace = "special:magic" }))

-- Mako notifications: dismiss top / dismiss all
bind(mainMod .. " + space",         "Notifications: Dismiss",             exec("makoctl dismiss"))
bind(mainMod .. " + space",         "Notifications: Dismiss board toast", global("quickshell:dismisstoast"))
bind(mainMod .. " + SHIFT + space", "Notifications: Dismiss all",         exec("makoctl dismiss --all"))

-- Scroll through existing workspaces with mainMod + scroll
bind(mainMod .. " + mouse_down", "Workspaces: Next workspace",     hl.dsp.focus({ workspace = "e+1" }))
bind(mainMod .. " + mouse_up",   "Workspaces: Previous workspace", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
bind(mainMod .. " + mouse:272", "Windows: Drag to move",   hl.dsp.window.drag(),   { mouse = true })
bind(mainMod .. " + mouse:273", "Windows: Drag to resize", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
bind("XF86AudioRaiseVolume",  "Media: Volume up",        exec("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
bind("XF86AudioLowerVolume",  "Media: Volume down",      exec("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
bind("XF86AudioMute",         "Media: Mute",             exec("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
bind("XF86AudioMicMute",      "Media: Mute microphone",  exec("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
bind("XF86MonBrightnessUp",   "Media: Brightness up",    exec("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
bind("XF86MonBrightnessDown", "Media: Brightness down",  exec("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
bind("XF86AudioNext",  "Media: Next track",    exec("playerctl next"),       { locked = true })
bind("XF86AudioPause", "Media: Play or pause", exec("playerctl play-pause"), { locked = true })
bind("XF86AudioPlay",  "Media: Play or pause", exec("playerctl play-pause"), { locked = true })
bind("XF86AudioPrev",  "Media: Previous track", exec("playerctl previous"),  { locked = true })


