---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

hl.window_rule({
    name  = "flameshot",
    match = { class = "flameshot" },

    move       = "0 0",
    pin        = true,
    float      = true,
    fullscreen = true,
})

-- Zen browser transparency — translucent whole window, like the terminal.
-- Hyprland's global blur (decoration > blur) gives the frosted-glass effect.
-- Tune the number below: lower = more see-through (0.75 matches Ghostty).
hl.window_rule({
    name  = "zen-transparency",
    match = { class = "^zen$" },

    opacity = "0.85 0.85",
})

-- Keep fullscreen Zen (videos, presentations) fully opaque.
hl.window_rule({
    name  = "zen-fullscreen-opaque",
    match = { class = "^zen$", fullscreen = true },

    opacity = "1.0 1.0",
})

-- Frosted mako notifications — mako's background is ~90% opaque (theme
-- mako.conf); ignore_alpha keeps the blur off the fully transparent corners.
hl.layer_rule({
    name  = "mako-blur",
    match = { namespace = "notifications" },

    blur         = true,
    ignore_alpha = 0.3,
})
